&lt;li style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot; data-start=&quot;2219&quot; data-end=&quot;2304&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Serve as a key liaison between physicians, patients, families, and internal teams&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot; data-start=&quot;2305&quot; data-end=&quot;2363&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Support care delivery through in-home visits as needed&lt;/span&gt;&lt;/li&gt;
