&lt;h3 data-start=&quot;2370&quot; data-end=&quot;2400&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;strong data-start=&quot;2374&quot; data-end=&quot;2400&quot;&gt;What We’re Looking For&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
