&lt;li style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot; data-start=&quot;3245&quot; data-end=&quot;3303&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Ability to proactively identify issues and take action&lt;/span&gt;&lt;/li&gt;
