&lt;ul data-start=&quot;3403&quot; data-end=&quot;3609&quot;&gt;
&lt;li style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot; data-start=&quot;3403&quot; data-end=&quot;3447&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Competitive compensation + full benefits&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot; data-start=&quot;3448&quot; data-end=&quot;3477&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;401(k) with company match&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot; data-start=&quot;3478&quot; data-end=&quot;3535&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Tuition reimbursement and career growth opportunities&lt;/span&gt;&lt;/li&gt;
